<script setup lang="ts">
import { eventInstant } from '@/Components/InvitationTemplates/referenceExperience';
import InputError from '@/Components/InputError.vue';
import InvitationPreviewRenderer from '@/Components/InvitationPreviewRenderer.vue';
import PageHeader from '@/Components/UI/PageHeader.vue';
import AuthenticatedLayout from '@/Layouts/AuthenticatedLayout.vue';
import { Head, Link, router, useForm } from '@inertiajs/vue3';
import { computed, nextTick, onBeforeUnmount, onMounted, ref, watch } from 'vue';

const props = defineProps<{ event: any; templates: any[]; activities: any[]; meals: any[]; giftMethods: any[]; previewParties: any[]; previewInvitation: any; timezones: string[]; urls: Record<string, string>; isLive: boolean }>();
const sections = [
    { key: 'personal', label: 'Personal Details' }, { key: 'meeting', label: 'Meeting Point' }, { key: 'ceremony', label: 'Ceremony & Venue' }, { key: 'story', label: 'Our Story' },
    { key: 'gifts', label: 'Gift Registry' }, { key: 'ending', label: 'Ending Page' }, { key: 'languages', label: 'Languages' }, { key: 'preview', label: 'Preview & Complete' },
];
const section = ref('personal');
const mobilePreview = ref(false);
const previewPartyId = ref<number | ''>('');
const saveState = ref<'idle' | 'saving' | 'saved' | 'error'>('idle');
const showTemplates = ref(false);
const previewMode = ref<'section' | 'full'>('full');
const previewViewport = ref<HTMLElement | null>(null);
const completing = ref(false);
const form = useForm({ ...props.event, settings: { palette_key: props.event.settings.palette_key || '', font_pair_key: props.event.settings.font_pair_key || '' }, content: { ...props.event.content }, gift_methods: props.giftMethods.map((method) => ({ ...method })) });
const selectedTemplate = computed(() => props.templates.find((template) => template.id === Number(form.template_id)) || null);
const paletteOptions = computed(() => selectedTemplate.value?.palettes || []);
const fontPairOptions = computed(() => selectedTemplate.value?.font_pairs || []);
const previewParty = computed(() => props.previewParties.find((party) => party.id === Number(previewPartyId.value)) || null);
const meetings = computed(() => props.activities.filter((activity) => activity.activity_type === 'meeting_point'));
const celebrations = computed(() => props.activities.filter((activity) => activity.activity_type !== 'meeting_point'));
const locale = computed(() => form.content.primary_locale === 'ar' ? 'ar' : 'en');
const preview = computed(() => ({
    ...props.previewInvitation,
    party_name: previewParty.value?.name || null,
    media: selectedTemplate.value?.preview_media || {},
    preview_context: { party: previewParty.value, meals: props.meals.filter(meal => meal.is_active), closed: false },
    template: selectedTemplate.value ? { name: selectedTemplate.value.name, component_key: selectedTemplate.value.component_key } : props.previewInvitation.template,
    settings: { ...props.previewInvitation.settings, ...(paletteOptions.value.find((item: any) => item.key === (form.settings.palette_key || selectedTemplate.value?.default_palette_key)) || {}), ...(fontPairOptions.value.find((item: any) => item.key === (form.settings.font_pair_key || selectedTemplate.value?.default_font_pair_key)) || {}) },
    content: { ...form.content }, gift_methods: form.gift_methods.filter((method: any) => method.is_active),
    event: { ...props.previewInvitation.event, date_iso: form.main_date, countdown_at: eventInstant(form.main_date, form.start_time, form.event_timezone), title: form.title, description: form.description, timezone: form.event_timezone, event_type: form.event_type?.replaceAll('_', ' '), host_name: form.host_name, second_host_name: form.second_host_name, venue: form.venue, address: form.address, location_url: form.location_url, dress_code: form.dress_code, parking_information: form.parking_information, transportation_information: form.transportation_information, accommodation_information: form.accommodation_information, guest_information: form.guest_information, main_date: form.main_date ? new Intl.DateTimeFormat(locale.value, { weekday: 'long', month: 'long', day: 'numeric', year: 'numeric' }).format(new Date(`${form.main_date}T00:00:00`)) : null, start_time: form.start_time ? new Intl.DateTimeFormat(locale.value, { hour: 'numeric', minute: '2-digit' }).format(new Date(`2000-01-01T${form.start_time}`)) : null, end_date: form.main_date && form.start_time && form.end_time && form.end_time < form.start_time ? new Intl.DateTimeFormat(locale.value, { weekday: 'long', month: 'long', day: 'numeric', year: 'numeric' }).format(new Date(new Date(`${form.main_date}T00:00:00`).setDate(new Date(`${form.main_date}T00:00:00`).getDate() + 1))) : null, end_time: form.end_time ? new Intl.DateTimeFormat(locale.value, { hour: 'numeric', minute: '2-digit' }).format(new Date(`2000-01-01T${form.end_time}`)) : null, rsvp_deadline: form.rsvp_deadline ? new Intl.DateTimeFormat(locale.value, { month: 'long', day: 'numeric', year: 'numeric' }).format(new Date(`${form.rsvp_deadline}T00:00:00`)) : null },
}));
const dirty = computed(() => form.isDirty);
const nextDay = computed(() => Boolean(form.start_time && form.end_time && form.end_time < form.start_time));
const changeSection = (key: string) => { section.value = key; };
const browseTemplates = () => { section.value = 'personal'; showTemplates.value = true; };
const addGiftMethod = () => form.gift_methods.push({ label: '', details: '', external_url: '', display_order: form.gift_methods.length, is_active: true });
const removeGiftMethod = (index: number) => form.gift_methods.splice(index, 1);
const save = () => { saveState.value = 'saving'; form.put(props.urls.save, { preserveScroll: true, onSuccess: () => { form.gift_methods = props.giftMethods.map((method) => ({ ...method })); form.defaults(); saveState.value = 'saved'; }, onError: () => { saveState.value = 'error'; } }); };
const complete = () => { if (dirty.value || completing.value) return; completing.value = true; router.post(props.urls.publish, {}, { onFinish: () => { completing.value = false; } }); };
watch([section, previewMode, mobilePreview], async () => {
    await nextTick();
    const viewport = previewViewport.value;
    if (!viewport) return;
    const selectors: Record<string, string> = { personal: 'header', meeting: 'ol', ceremony: '[class*="-location"], [class*="-venue"]', story: '[data-section="story"]', gifts: '[data-section="gifts"]', ending: '[data-section="ending"]' };
    const target = previewMode.value === 'section' ? viewport.querySelector(selectors[section.value] || 'header') : null;
    viewport.scrollTo({ top: target ? target.getBoundingClientRect().top - viewport.getBoundingClientRect().top + viewport.scrollTop : 0 });
});
const beforeUnload = (event: BeforeUnloadEvent) => { if (dirty.value) { event.preventDefault(); event.returnValue = ''; } };
watch(() => form.template_id, (current, previous) => { if (previous !== undefined && current !== previous) { form.settings.palette_key = ''; form.settings.font_pair_key = ''; } });
watch(dirty, (value) => { if (value && saveState.value === 'saved') saveState.value = 'idle'; });
onMounted(() => window.addEventListener('beforeunload', beforeUnload));
onBeforeUnmount(() => window.removeEventListener('beforeunload', beforeUnload));
</script>

<template>
