        <main class="fe-page fe-page-wide space-y-5" :dir="locale === 'ar' ? 'rtl' : 'ltr'">
            <div class="space-y-3 rounded-2xl border border-[color:var(--fe-border)] bg-[color:var(--fe-surface)] p-3 shadow-sm"><nav class="flex max-w-full gap-2 overflow-x-auto" aria-label="Invitation personalization sections"><button v-for="(item, index) in sections" :key="item.key" type="button" class="shrink-0 rounded-full px-4 py-2 text-sm font-semibold" :class="section === item.key ? 'bg-[color:var(--fe-primary)] text-white shadow-sm' : 'bg-[color:var(--fe-surface-elevated)] text-[color:var(--fe-text-secondary)]'" @click="changeSection(item.key)"><span class="me-1 opacity-70">{{ index + 1 }}</span>{{ item.label }}</button></nav><div class="flex flex-wrap items-center justify-between gap-3 border-t border-[color:var(--fe-border)] pt-3"><div class="min-w-0"><p class="text-[0.68rem] font-semibold uppercase tracking-[0.18em] text-[color:var(--fe-text-muted)]">Current template</p><p class="truncate font-semibold">{{ selectedTemplate?.name || 'Choose a design' }}</p></div><button type="button" class="text-sm font-semibold text-[color:var(--fe-primary)] underline" @click="browseTemplates">Browse</button><div class="flex flex-wrap items-center gap-2"><span v-if="saveState === 'saving'" class="text-sm text-[color:var(--fe-text-muted)]">Saving...</span><span v-else-if="saveState === 'saved'" class="text-sm font-medium text-emerald-700">Saved</span><span v-else-if="saveState === 'error'" class="text-sm font-medium text-red-700">Could not save</span><button type="button" class="fe-btn fe-btn-secondary xl:hidden" @click="mobilePreview = !mobilePreview">{{ mobilePreview ? 'Hide Preview' : 'Preview Invitation' }}</button><button type="button" :disabled="form.processing || !dirty" class="fe-btn fe-btn-primary" @click="save">{{ form.processing ? 'Saving...' : 'Save Changes' }}</button></div></div></div>
            <ul v-if="Object.keys(form.errors).length" class="rounded-xl border border-red-200 bg-red-50 p-4 text-sm text-red-800" role="alert"><li v-for="(error, field) in form.errors" :key="field">{{ error }}</li></ul><div class="grid gap-6 xl:grid-cols-[minmax(0,1.5fr)_minmax(0,1fr)]">
                <section class="fe-card min-w-0 p-5 sm:p-7">
                    <div v-if="section === 'personal'" class="space-y-5"><div><p class="fe-page-eyebrow">Personal Details</p><h2 class="fe-section-title mt-1">Set the invitation’s identity and key timing.</h2></div><div class="grid gap-4 sm:grid-cols-2"><label>Event type<select v-model="form.event_type" class="mt-1 w-full"><option v-for="type in ['wedding','engagement','bridal_shower','birthday','graduation','baptism','communion']" :key="type" :value="type">{{ type.replaceAll('_', ' ') }}</option></select><InputError :message="form.errors.event_type" /></label><label>Invitation title<input v-model="form.title" class="mt-1 w-full" /><InputError :message="form.errors.title" /></label><label>First host<input v-model="form.host_name" class="mt-1 w-full" /><InputError :message="form.errors.host_name" /></label><label>Second host <span class="text-[color:var(--fe-text-muted)]">(optional)</span><input v-model="form.second_host_name" class="mt-1 w-full" /></label><label>Event date<input v-model="form.main_date" type="date" class="mt-1 w-full" /><InputError :message="form.errors.main_date" /></label><label>RSVP deadline<input v-model="form.rsvp_deadline" type="date" class="mt-1 w-full" /><InputError :message="form.errors.rsvp_deadline" /></label><label>Start time<input v-model="form.start_time" type="time" class="mt-1 w-full" /><InputError :message="form.errors.start_time" /></label><label>End time <span class="text-[color:var(--fe-text-muted)]">(optional)</span><input v-model="form.end_time" type="time" class="mt-1 w-full" /><p v-if="nextDay" class="mt-1 text-xs font-medium text-[color:var(--fe-accent)]">Ends the next day</p><InputError :message="form.errors.end_time" /></label><label class="sm:col-span-2">Timezone<select v-model="form.event_timezone" class="mt-1 w-full"><option v-for="zone in timezones" :key="zone" :value="zone">{{ zone }}</option></select><InputError :message="form.errors.event_timezone" /></label></div><div class="border-t border-[color:var(--fe-border)] pt-5"><div class="flex items-center justify-between gap-3"><div><h3 class="font-semibold">Template presentation</h3><p class="fe-section-copy mt-1">Choose a trusted color and type pairing for the selected template.</p></div><button type="button" class="text-sm font-semibold text-[color:var(--fe-primary)] underline" @click="showTemplates = !showTemplates">{{ showTemplates ? 'Hide designs' : 'Browse designs' }}</button></div><div v-if="showTemplates" class="mt-4 grid gap-3 sm:grid-cols-3"><button v-for="template in templates" :key="template.id" type="button" class="rounded border p-4 text-left" :class="Number(form.template_id) === template.id ? 'border-[color:var(--fe-primary)] bg-[#f9ece7]' : 'border-[color:var(--fe-border)]'" @click="form.template_id = template.id"><p class="font-semibold">{{ template.name }}</p><p class="mt-1 text-sm text-[color:var(--fe-text-secondary)]">{{ template.description }}</p></button></div><InputError :message="form.errors.template_id" /><div v-if="paletteOptions.length || fontPairOptions.length" class="mt-4 grid gap-4 sm:grid-cols-2"><label v-if="paletteOptions.length">Color style<select v-model="form.settings.palette_key" class="mt-1 w-full"><option value="">Default</option><option v-for="option in paletteOptions" :key="option.key" :value="option.key">{{ option.label }}</option></select></label><label v-if="fontPairOptions.length">Typography<select v-model="form.settings.font_pair_key" class="mt-1 w-full"><option value="">Default</option><option v-for="option in fontPairOptions" :key="option.key" :value="option.key">{{ option.label }}</option></select></label></div></div></div>
