                    <div v-else-if="section === 'languages'" class="space-y-5"><div><p class="fe-page-eyebrow">Languages</p><h2 class="fe-section-title mt-1">Choose the primary invitation language.</h2><p class="fe-section-copy mt-2">Arabic uses a right-to-left layout. Enter your invitation wording in the selected language; automatic translation is not included.</p></div><label class="block max-w-sm">Primary invitation language<select v-model="form.content.primary_locale" class="mt-1 w-full"><option value="en">English</option><option value="ar">العربية (Arabic)</option></select><InputError :message="form.errors['content.primary_locale']" /></label></div>
