                </section>
                <aside aria-label="Live invitation preview" class="min-w-0 xl:sticky xl:top-6 xl:self-start" :class="{ 'hidden xl:block': !mobilePreview }"><div class="mb-3 rounded-2xl border border-[color:var(--fe-border)] bg-[color:var(--fe-surface)] p-4"><p class="text-[0.68rem] font-semibold uppercase tracking-[0.18em] text-[color:var(--fe-text-muted)]">Preview mode</p><div class="mt-2 flex gap-2"><button type="button" class="rounded px-3 py-1 text-sm" :class="previewMode === 'section' ? 'bg-[color:var(--fe-primary)] text-white' : 'bg-[color:var(--fe-surface-elevated)]'" @click="previewMode = 'section'">Current section</button><button type="button" class="rounded px-3 py-1 text-sm" :class="previewMode === 'full' ? 'bg-[color:var(--fe-primary)] text-white' : 'bg-[color:var(--fe-surface-elevated)]'" @click="previewMode = 'full'">Full invitation</button></div><p class="mt-2 text-sm text-[color:var(--fe-text-secondary)]">{{ previewMode === 'section' ? sections.find((item) => item.key === section)?.label : 'Full invitation' }}</p><label class="mt-4 block text-sm font-semibold">Preview for<select v-model="previewPartyId" class="mt-1 w-full"><option value="">Generic Invitation</option><option v-for="party in previewParties" :key="party.id" :value="party.id">{{ party.name }} · {{ party.maximum_attendees }} guests</option></select></label><Link :href="previewPartyId ? `${urls.preview}?party_id=${previewPartyId}` : urls.preview" class="mt-4 inline-flex text-sm font-semibold text-[color:var(--fe-primary)] underline">Open full preview</Link></div><div class="mx-auto max-w-[24rem] overflow-hidden rounded-[2rem] border-8 border-stone-800 bg-white shadow-xl"><div ref="previewViewport" style="contain: layout paint; transform: translateZ(0)" class="h-[38rem] max-h-[70dvh] overflow-y-auto overscroll-contain" tabindex="0" aria-label="Invitation phone screen"><InvitationPreviewRenderer :invitation="preview" /></div></div><Link :href="urls.guests" class="mt-4 inline-flex text-sm font-semibold text-[color:var(--fe-primary)] underline">Manage Families &amp; Guests</Link></aside>
            </div>
        </main>
    </AuthenticatedLayout>
</template>

<style scoped>
